import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  selectUsersState,
  updateUserAsync,
  deleteUserAsync,
} from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  const handleChange = (id, key, value) => {
    const updatedUser = users.find(u => u.id === id);
    if (updatedUser) {
      dispatch(updateUserAsync({ ...updatedUser, [key]: value }));
    }
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this user?")) {
      dispatch(deleteUserAsync(id));
    }
  };

  if (loading) return <p>Loading users...</p>;
  if (error) return <p style={{ color: "red" }}>Error: {error}</p>;

  return (
    <div className="userlist-dashboard">
      <h2>User Management</h2>
      <div className="user-cards-container">
        {users.length > 0 ? (
          users.map((u) => (
            <div className="user-card" key={u.id}>
              <div className="user-card-header">
                <span>User ID: {u.id}</span>
              </div>
              <div className="user-info">
                <div>
                  <label>Username</label>
                  <input
                    type="text"
                    value={u.username}
                    onChange={(e) => handleChange(u.id, "username", e.target.value)}
                  />
                </div>
                <div>
                  <label>Email</label>
                  <input
                    type="text"
                    value={u.email}
                    onChange={(e) => handleChange(u.id, "email", e.target.value)}
                  />
                </div>
                <div>
                  <label>Status</label>
                  <select
                    value={u.is_active ? "Active" : "Inactive"}
                    onChange={(e) =>
                      handleChange(u.id, "is_active", e.target.value === "Active")
                    }
                  >
                    <option>Active</option>
                    <option>Inactive</option>
                  </select>
                </div>
              </div>
              <div className="user-actions">
                <button className="save-btn" onClick={() => handleChange(u.id)}>
                  Save
                </button>
                <button className="delete-btn" onClick={() => handleDelete(u.id)}>
                  Delete
                </button>
              </div>
            </div>
          ))
        ) : (
          <p>No users found</p>
        )}
      </div>
    </div>
  );
}

export default UserList;
